import{_ as t,o as a,c as r,an as s}from"./chunks/framework.BAJgIXXb.js";const u=JSON.parse('{"title":"OSCP · Rapport d’audit","description":"Préparer les captures, vérifier leur intégrité et rédiger un constat.","frontmatter":{"title":"OSCP · Rapport d’audit","description":"Préparer les captures, vérifier leur intégrité et rédiger un constat."},"headers":[],"relativePath":"oscp/rapport.md","filePath":"oscp/rapport.md"}'),i={name:"oscp/rapport.md"};function o(n,e,l,p,d,c){return a(),r("div",null,e[0]||(e[0]=[s('<h1 id="rapport-d-audit" tabindex="-1">Rapport d’audit <a class="header-anchor" href="#rapport-d-audit" aria-label="Permalink to &quot;Rapport d’audit&quot;">​</a></h1><h2 id="garder-le-contexte-d-une-preuve" tabindex="-1">Garder le contexte d’une preuve <a class="header-anchor" href="#garder-le-contexte-d-une-preuve" aria-label="Permalink to &quot;Garder le contexte d’une preuve&quot;">​</a></h2><p>Pour chaque constat, note la machine, le compte utilisé, la commande exacte et sa sortie. Conserve une capture lisible qui montre le résultat et permet d’identifier le système concerné.</p><table tabindex="0"><thead><tr><th>Élément</th><th>À consigner</th></tr></thead><tbody><tr><td>Périmètre</td><td>Machine et service concernés.</td></tr><tr><td>Observation</td><td>Action réalisée, résultat obtenu et nom de la capture.</td></tr><tr><td>Impact</td><td>Conséquence effectivement observée pendant le test.</td></tr><tr><td>Correction</td><td>Mesure proposée et résultat attendu après correction.</td></tr></tbody></table><p>Pour l’examen, vérifie les consignes de capture et de remise du rapport dans le <a href="https://help.offsec.com/hc/en-us/articles/360040165632-OSCP-Exam-Guide" target="_blank" rel="noreferrer">guide officiel OffSec</a>.</p><h2 id="capturer-une-fenetre" tabindex="-1">Capturer une fenêtre <a class="header-anchor" href="#capturer-une-fenetre" aria-label="Permalink to &quot;Capturer une fenêtre&quot;">​</a></h2><h3 id="sous-windows" tabindex="-1">Sous Windows <a class="header-anchor" href="#sous-windows" aria-label="Permalink to &quot;Sous Windows&quot;">​</a></h3><p>Appuie sur <strong>Windows + Maj + S</strong>, sélectionne la zone utile et enregistre l’image sous <code>capture.png</code>.</p><h3 id="sous-kali-avec-gnome-screenshot" tabindex="-1">Sous Kali avec GNOME Screenshot <a class="header-anchor" href="#sous-kali-avec-gnome-screenshot" aria-label="Permalink to &quot;Sous Kali avec GNOME Screenshot&quot;">​</a></h3><p>Si <code>gnome-screenshot</code> est installé, sélectionne la zone à enregistrer dans le dossier courant.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">gnome-screenshot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -a</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> ./capture.png</span></span></code></pre></div><h2 id="controler-l-integrite-d-une-capture" tabindex="-1">Contrôler l’intégrité d’une capture <a class="header-anchor" href="#controler-l-integrite-d-une-capture" aria-label="Permalink to &quot;Contrôler l’intégrité d’une capture&quot;">​</a></h2><p>Exécute la commande depuis le dossier contenant <code>capture.png</code>. Conserve l’empreinte avec les notes pour la comparer à celle d’une copie ultérieure.</p><h3 id="sha-256-sous-linux" tabindex="-1">SHA-256 sous Linux <a class="header-anchor" href="#sha-256-sous-linux" aria-label="Permalink to &quot;SHA-256 sous Linux&quot;">​</a></h3><p><code>sha256sum</code> affiche l’empreinte et le chemin de la capture.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> ./capture.png</span></span></code></pre></div><h3 id="sha-256-sous-windows-avec-powershell" tabindex="-1">SHA-256 sous Windows avec PowerShell <a class="header-anchor" href="#sha-256-sous-windows-avec-powershell" aria-label="Permalink to &quot;SHA-256 sous Windows avec PowerShell&quot;">​</a></h3><p>Relève la valeur de la colonne <code>Hash</code>.</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">Get-FileHash</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">LiteralPath </span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;">&#39;.\\capture.png&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">Algorithm SHA256</span></span></code></pre></div><h2 id="rediger-le-rapport" tabindex="-1">Rédiger le rapport <a class="header-anchor" href="#rediger-le-rapport" aria-label="Permalink to &quot;Rédiger le rapport&quot;">​</a></h2><p>Relie chaque constat à sa preuve et à une correction. Si le mandat prévoit une analyse de conformité, cite l’exigence concernée et la pièce qui permet de la vérifier.</p><p><a href="https://help.offsec.com/hc/en-us/articles/360046787731-OSCP-Reporting-Requirements" target="_blank" rel="noreferrer">Consignes de rapport OffSec</a> · <a href="https://docs.sysreptor.com/offsec-reporting-with-sysreptor/" target="_blank" rel="noreferrer">Modèle OffSec pour SysReptor</a> · <a href="https://www.gnu.org/software/coreutils/manual/coreutils.html" target="_blank" rel="noreferrer">GNU Coreutils</a> · <a href="https://learn.microsoft.com/powershell/module/microsoft.powershell.utility/get-filehash" target="_blank" rel="noreferrer">Get-FileHash</a>.</p><p>Sources d’origine : <a href="https://github.com/krovs/oscp-notes/blob/main/README.md" target="_blank" rel="noreferrer">notes de krovs</a> et <a href="https://www.emmanuelsolis.com/oscp.html" target="_blank" rel="noreferrer">guide d’Emmanuel Solis</a>.</p>',23)]))}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
